custom_css:
.yaycheckout-soft-steps-actions .yaycheckout-step-button,
.yaycheckout-soft-steps-actions .yaycheckout-back-button {
	width: 100%;
	box-sizing: border-box;
	justify-content: center;
}

/* Phones: logo and total share the first line; the step dots get a line of their own. */
@media (max-width: 480px) {
	.yaycheckout-soft-steps-bar {
		flex-wrap: wrap;
		row-gap: 8px;
		padding: 12px 0;
	}

	.yaycheckout-soft-steps-bar .yaycheckout-steps-progress {
		order: 3;
		flex-basis: 100%;
	}
}
